-- v5: каталог игр и категорий (список с funpay.com, предоставлен владельцем). Выполняется один раз.
create table if not exists seed_flags(key text primary key);
do $$ begin
if exists (select 1 from seed_flags where key='games_v5') then return; end if;
insert into categories(slug,name) values ('prime-gaming','Prime Gaming'),('raids','Рейды'),('pvp','PvP'),('region','Смена региона'),('timecards','Тайм карты'),('clans','Кланы и гильдии') on conflict (slug) do nothing;
insert into games(slug,name)
 select case when exists(select 1 from games x where x.slug=v.slug) then v.slug||'-'||substr(md5(v.name),1,4) else v.slug end, v.name
